'use strict';
const $=id=>document.getElementById(id),t=OrionI18n.t;
const orders=[[0,1,2,3],[2,0,3,1],[1,3,0,2],[3,2,1,0],[0,2,1,3],[2,3,0,1]];
const names=[['A · Shell','A · 貝殼'],['B · Leaf','B · 葉片'],['C · Ripple','C · 波紋'],['D · Pebbles','D · 卵石']];
const marks=['<path d="M8 30Q-2 5 20 3Q42 5 32 30Z M20 29L8 9 M20 29V5 M20 29L32 9 M20 29L3 18 M20 29L37 18"/>','<path d="M5 35Q1 0 35 4Q40 35 5 35Z M5 35L30 9 M13 27L10 15 M20 20L31 21"/>','<path d="M2 8Q10 0 20 8T38 8 M2 20Q10 12 20 20T38 20 M2 32Q10 24 20 32T38 32"/>','<ellipse cx="11" cy="11" rx="8" ry="6"/><ellipse cx="29" cy="25" rx="8" ry="9"/><ellipse cx="10" cy="31" rx="6" ry="5"/>'];
let variant=OrionProgress.variant('strata'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget;
let stage=0,stack=[],gap=-1,solved=false,hintDepth=0,state='ready',saveFailed=false,drag=null;
function challenge(v=variant,s=stage){const oldest=orders[(v+s*2)%6].slice();return {oldest,boundary:(v+s)%3};}
function label(id){return t(...names[id]);}
function resetTrial(){const q=challenge(),top=q.oldest.slice().reverse();stack=[top[1],top[2],top[3],top[0]];gap=-1;solved=false;hintDepth=0;state='ready';saveFailed=false;cancelDrag();$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('strata')){variant=v;stage=0;resetTrial();}
function move(from,to){if(solved||drag||!Number.isInteger(from)||!Number.isInteger(to)||from<0||to<0||from>3||to>3||from===to)return;const id=stack.splice(from,1)[0];stack.splice(to,0,id);gap=-1;state='ready';render();}
function place(n){if(solved||drag||!Number.isInteger(n)||n<0||n>2)return;gap=n;state='ready';render();}
function check(){if(solved||drag)return;const q=challenge();if(!stack.every((x,i)=>x===q.oldest[3-i]))state='order';else if(gap<0)state='missing';else if(gap!==2-q.boundary)state='gap';else{solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('deeptime');}render();if(solved&&stage<2)$('next').focus();}
function cancelDrag(){if(drag){drag.row.classList.remove('dragging');drag=null;}}
function dragStart(e){if(solved||drag||e.button!==undefined&&e.button!==0)return;const handle=e.target.closest?.('[data-grab]');if(!handle)return;const row=handle.closest('[data-row]');drag={id:e.pointerId,index:Number(row.dataset.row),row};row.classList.add('dragging');$('column').setPointerCapture?.(e.pointerId);e.preventDefault();}
function dragEnd(e,cancel=false){if(!drag||drag.id!==e.pointerId)return;const from=drag.index,row=!cancel&&document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-row]');cancelDrag();if(row)move(from,Number(row.dataset.row));}
function hints(){const q=challenge();return[t('Imagine laying blankets down one by one. The first stays underneath. These rock layers have not been overturned.','想像逐張鋪下毛毯，第一張留在下面。這些岩層沒有倒轉。'),t('Earlier deposits belong below later deposits. Read each “before” clue, then work from the bottom upward.','較早沉積的岩層放在較後的下面。閱讀每條「之前」線索，從底部往上排列。'),t(`Bottom → top: ${q.oldest.map(label).join(' → ')}. Put the marker above ${label(q.oldest[q.boundary])} and below ${label(q.oldest[q.boundary+1])}.`,`底 → 頂：${q.oldest.map(label).join(' → ')}。標記放在${label(q.oldest[q.boundary])}上方、${label(q.oldest[q.boundary+1])}下方。`)];}
function render(){const q=challenge(),complete=solved&&stage===2,progress=stage+Number(solved);window.OrionDiscovery?.update(complete);document.title=t('The Fossil Staircase · Orion','化石階梯 · Orion');$('stageTitle').textContent=t(`Column ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 組岩層 · 題組 ${variant+1}`);$('sceneStatus').textContent=t(`Stone seals · ${progress} / 3`,`岩層封印 · ${progress} / 3`);$('seals').textContent=Array.from({length:3},(_,i)=>i<progress?'◆':'◇').join(' ');$('scene').classList.toggle('complete',complete);
$('column').innerHTML=stack.map((id,i)=>`<div class="layer" data-row="${i}" data-sample="${id}"><span class="grab" data-grab="${id}"><svg viewBox="0 0 40 40" aria-hidden="true">${marks[id]}</svg><strong>${label(id)}</strong></span><button data-move="${i}" data-dir="-1" aria-label="${t('Move up','向上移動')} ${label(id)}" ${solved||i===0?'disabled':''}>↑</button><button data-move="${i}" data-dir="1" aria-label="${t('Move down','向下移動')} ${label(id)}" ${solved||i===3?'disabled':''}>↓</button></div>${i<3?`<button class="gap" data-gap="${i}" aria-pressed="${gap===i}" ${solved?'disabled':''} aria-label="${t(`Place marker between ${label(id)} and ${label(stack[i+1])}`,`在${label(id)}和${label(stack[i+1])}之間放標記`)}">${gap===i?t('◆ Treasure marker','◆ 寶藏標記'):t('┄ Place marker here ┄','┄ 在這裏放標記 ┄')}</button>`:''}`).join('');
$('clues').innerHTML='<ul>'+[1,0,2].map(i=>`<li>${t(`${label(q.oldest[i])} settled before ${label(q.oldest[i+1])}.`,`${label(q.oldest[i])}在${label(q.oldest[i+1])}之前沉積。`)}</li>`).join('')+'</ul>';
$('goal').textContent=t(`Story event: place the treasure marker after ${label(q.oldest[q.boundary])} settled, but before ${label(q.oldest[q.boundary+1])} settled.`,`故事事件：寶藏標記在${label(q.oldest[q.boundary])}沉積之後、${label(q.oldest[q.boundary+1])}沉積之前。`);
$('reading').textContent=gap<0?t('No marker placed yet. Moving a layer clears the marker.','尚未放置標記。移動岩層會清除標記。'):t(`Marker: below ${label(stack[gap])}, above ${label(stack[gap+1])}.`,`標記：${label(stack[gap])}下方、${label(stack[gap+1])}上方。`);
const messages={ready:['Use the notes to rebuild the layers and place the marker.','根據筆記重組岩層，再放置標記。'],order:['Check the layer order. In this undisturbed column, an earlier layer belongs underneath a later one.','再看看岩層次序。未受擾動的岩層中，較早的一層在較後的一層下面。'],missing:['The layers fit the notes! Now place the treasure marker in a gap.','岩層符合筆記！現在把寶藏標記放進空隙。'],gap:['The layers fit. The marker must be above the earlier event and below the later event.','岩層正確。標記應在較早事件上方、較後事件下方。'],success:['The stone memory is restored. A staircase seal shines!','石頭記憶重現，階梯封印亮起了！']};$('feedback').textContent=t(...messages[state]);
$('check').hidden=solved;$('retry').hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved||hintDepth===3;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintDepth>0));$('hints').hidden=!hintDepth;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('');$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('deeptime')?t('Deep Time Sigil saved in your collection.','遠古符印已存入收藏。'):'';}
$('column').onclick=e=>{const b=e.target.closest?.('button');if(!b||b.disabled)return;if(b.dataset.gap!==undefined)place(Number(b.dataset.gap));else if(b.dataset.move!==undefined){const from=Number(b.dataset.move),dir=Number(b.dataset.dir);move(from,from+dir);const i=from+dir;document.querySelector(`#column button[data-move="${i}"][data-dir="${i===0?1:i===3?-1:dir}"]`)?.focus();}};
$('column').onpointerdown=dragStart;$('column').onpointerup=e=>dragEnd(e);$('column').onpointercancel=e=>dragEnd(e,true);$('column').onlostpointercapture=e=>dragEnd(e,true);window.addEventListener('keydown',e=>{if(e.key==='Escape')cancelDrag();});
$('check').onclick=check;$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();$('check').focus();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);render();};$('replay').onclick=()=>{const v=OrionProgress.nextVariant('strata',variant);observedVariant=OrionProgress.variant('strata');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('deeptime');render();};
function syncProgress(){const v=OrionProgress.variant('strata'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('deeptime')&&!saveFailed)resetMission();else render();}
window.addEventListener('orion-language',()=>{cancelDrag();render();});window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);window.addEventListener('pagehide',cancelDrag);resetMission();OrionI18n.apply();
